<template>
  <div class="interaction-workspace">
    <header class="chat-header">
      <div><div class="eyebrow">MODELDOCK WORKSPACE</div><h1>模型交互</h1><p>连续对话与本地模型运行记录都保存在当前工作区。</p></div>
      <a-space><a-tag color="green"><span class="status-dot" /> 本地运行</a-tag><a-button :icon="h(PlusOutlined)" @click="newChat">新建对话</a-button></a-space>
    </header>
    <div class="chat-layout">
      <section class="chat-panel">
        <div ref="messageList" class="message-list">
          <div v-if="!messages.length" class="welcome"><div class="welcome-mark">M</div><h2>开始一段模型对话</h2><p>选择模型后，可以连续追问、上传参考文件，并查看每次运行的过程。</p><div class="suggestions"><a-button v-for="item in suggestions" :key="item" @click="prompt = item">{{ item }}</a-button></div></div>
          <article v-for="item in messages" :key="item.id" class="chat-message" :class="item.role">
            <div class="avatar">{{ item.role === 'user' ? '你' : 'M' }}</div>
            <div class="message-content">
              <div class="message-meta"><strong>{{ item.role === 'user' ? '你' : selectedModelName }}</strong><span v-if="item.createdAt">{{ item.createdAt }}</span></div>
              <div v-if="item.role === 'user'" class="user-message-text">{{ item.content }}</div><MarkdownMessage v-else-if="item.content" :content="item.content" />
              <a-collapse v-if="item.steps?.length" v-model:active-key="item.stepsOpen" class="process-collapse" ghost><a-collapse-panel key="process"><template #header><span class="process-header"><LoadingOutlined v-if="item.running" spin /><CheckCircleOutlined v-else-if="item.processStatus === 'done'" /><CloseCircleOutlined v-else-if="item.processStatus === 'error' || item.processStatus === 'stopped'" /> 执行过程 <em>{{ item.running ? '运行中' : item.processStatus === 'stopped' ? '已停止' : item.processStatus === 'error' ? `执行失败${item.duration ? ` · ${item.duration}` : ''}` : `已完成${item.duration ? ` · ${item.duration}` : ''}` }}</em><a-button v-if="item.processStatus === 'stopped'" type="link" size="small" class="resume-task" @click.stop="retryMessage(item)">继续任务</a-button></span></template><div class="embedded-steps"><div v-for="step in item.steps" :key="step.key" class="agent-step" :class="step.status"><div class="step-icon"><CheckOutlined v-if="step.status === 'done'" /><CloseOutlined v-else-if="step.status === 'error' || step.status === 'stopped'" /><LoadingOutlined v-else-if="step.status === 'running'" spin /><span v-else>{{ step.index }}</span></div><div class="step-body"><strong>{{ step.label }}</strong><span>{{ step.status === 'running' ? (step.detail || stepMessage) : step.status === 'done' ? (step.detail || '已完成') : step.status === 'error' || step.status === 'stopped' ? (step.detail || '已停止') : '等待执行' }}<em v-if="step.status !== 'pending'"> · {{ formatDuration(step) }}</em></span></div></div></div></a-collapse-panel></a-collapse>
              <div v-if="item.artifactURL" class="message-artifact"><img v-if="item.artifactType === 'image'" :src="item.artifactURL" alt="生成结果" /><video v-else-if="item.artifactType === 'video'" :src="item.artifactURL" controls /><audio v-else-if="item.artifactType === 'audio'" :src="item.artifactURL" controls /><a :href="item.artifactURL" download><DownloadOutlined /> 下载 {{ item.artifactName || '生成结果' }}</a></div>
            </div>
          </article>
        </div>
        <div class="composer-wrap"><div v-if="image" class="attachment-chip"><PaperClipOutlined /> {{ image.name }} <CloseOutlined @click="image = undefined" /></div><div class="composer-bar"><a-upload :before-upload="beforeUpload" :max-count="1" accept="image/png,image/jpeg,image/webp,video/*,audio/*" :show-upload-list="false"><a-button type="text" :icon="h(PaperClipOutlined)" :disabled="running" /></a-upload><a-textarea v-model:value="prompt" :rows="2" :disabled="running" :placeholder="composerPlaceholder" @keydown.enter.exact.prevent="send" /><a-button v-if="running" class="send-button stop-button" :icon="h(StopOutlined)" @click="stopRun">停止</a-button><a-button v-else type="primary" class="send-button" :icon="h(SendOutlined)" @click="send">发送</a-button></div><div class="composer-hint">Enter 发送 · Shift + Enter 换行 <span>{{ selectedModelName }}</span></div></div>
      </section>
      <aside class="chat-sidebar">
        <a-card class="settings-card history-card" :bordered="false" title="历史对话"><template #extra><a-button type="text" size="small" :icon="h(PlusOutlined)" @click="newChat">新建</a-button></template><a-empty v-if="!history.length" image="simple" description="暂无历史对话" /><div v-else class="history-list"><div v-for="item in history" :key="item.id" class="history-item" :class="{ active: item.id === conversationId }" @click="switchConversation(item.id)"><div class="history-item-main"><strong>{{ item.title }}</strong><span>{{ item.updatedAt }}</span></div><div class="history-actions"><a-button type="text" size="small" title="重命名" @click.stop="renameConversation(item.id)">重命名</a-button><a-button type="text" danger size="small" title="删除" @click.stop="deleteConversation(item.id)">删除</a-button></div></div></div></a-card>
        <a-card class="settings-card" :bordered="false" title="模型"><a-select v-model:value="modelId" class="full-control" :options="availableModels" placeholder="选择可用模型" :option-label-prop="'label'" /><div class="model-summary"><span class="status-dot" />{{ selectedModelName || '尚未选择模型' }}<small>{{ capabilityLabel }}</small></div></a-card>
        <a-card class="settings-card" :bordered="false" title="运行参数"><div class="capability-tabs"><a-tag v-for="capability in capabilities" :key="capability" :color="capability === activeCapability ? 'blue' : 'default'">{{ capability }}</a-tag></div><template v-if="activeCapability === '文本'"><div class="setting-row"><span>温度</span><a-input-number v-model:value="temperature" :min="0" :max="2" :step="0.1" /></div><div class="setting-row"><span>最大输出</span><a-input-number v-model:value="maxTokens" :min="128" :max="32768" :step="128" /></div><a-checkbox v-model:checked="streaming">流式输出（运行时支持时）</a-checkbox></template><template v-else-if="activeCapability === '图片'"><div class="setting-row"><span>输出尺寸</span><a-select v-model:value="imageSize" :options="imageSizes" /></div><div class="setting-row"><span>采样步数</span><a-input-number v-model:value="imageSteps" :min="1" :max="30" /></div><div class="setting-row"><span>引导强度</span><a-input-number v-model:value="imageGuidance" :min="0.1" :max="10" :step="0.1" /></div><div class="setting-row"><span>随机种子</span><a-input-number v-model:value="imageSeed" :min="0" placeholder="随机" /></div><a-checkbox v-model:checked="promptExpansion">提示词扩展</a-checkbox></template><template v-else-if="activeCapability === '视频'"><div class="setting-row"><span>时长（秒）</span><a-input-number v-model:value="videoDuration" :min="1" :max="30" /></div><a-alert type="info" show-icon message="视频参数将由对应运行时处理" /></template><template v-else><div class="setting-row"><span>时长（秒）</span><a-input-number v-model:value="audioDuration" :min="1" :max="120" /></div><a-alert type="info" show-icon message="音频参数将由对应运行时处理" /></template></a-card>
        <a-card class="run-summary" :bordered="false" title="本次运行"><div class="summary-line"><span>状态</span><a-tag :color="running ? 'blue' : job?.status === 'failed' ? 'red' : job?.status === 'completed' ? 'green' : 'default'">{{ running ? '运行中' : job?.status === 'completed' ? '已完成' : job?.status === 'failed' ? '失败' : '待运行' }}</a-tag></div><div class="summary-line"><span>耗时</span><strong>{{ elapsed }}</strong></div><div class="summary-line"><span>当前阶段</span><span>{{ stepMessage }}</span></div></a-card>
      </aside>
    </div>
  </div>
</template>

<script setup lang="ts">
import { computed, h, nextTick, onMounted, onUnmounted, ref, watch } from 'vue'
import { Input, message, Modal } from 'ant-design-vue'
import { CheckCircleOutlined, CheckOutlined, CloseCircleOutlined, CloseOutlined, DownloadOutlined, LoadingOutlined, PaperClipOutlined, PlusOutlined, SendOutlined, StopOutlined } from '@ant-design/icons-vue'
import { api } from '../../services/api'
import type { ModelManifest } from '../../types/api'
import MarkdownMessage from '../../components/MarkdownMessage.vue'
type Step = { key: string; label: string; status: string; detail?: string; startedAt: string; finishedAt?: string; index?: number }
type ChatItem = { id: string; role: 'user' | 'assistant'; content: string; createdAt?: string; artifactURL?: string; artifactName?: string; artifactType?: string; steps?: Step[]; stepsOpen?: string[]; running?: boolean; processStatus?: string; duration?: string; interrupted?: boolean }
type ConversationEntry = { id: string; title: string; updatedAt: string }
const models = ref<ModelManifest[]>([]); const modelId = ref(''); const prompt = ref(''); const image = ref<File>(); const messages = ref<ChatItem[]>([]); const running = ref(false); const job = ref<Awaited<ReturnType<typeof api.generationJob>>>(); const stepMessage = ref('正在准备'); const elapsed = ref('00:00'); const startedAt = ref(0); const messageList = ref<HTMLElement>(); const conversationId = ref(localStorage.getItem('modeldock-active-conversation') || `conversation-${Date.now()}-${Math.random().toString(16).slice(2)}`); const imageSize = ref('1024x1024'); const imageSteps = ref(6); const imageGuidance = ref(1); const imageSeed = ref<number>(); const promptExpansion = ref(false); const temperature = ref(0.7); const maxTokens = ref(2048); const streaming = ref(true); const videoDuration = ref(5); const audioDuration = ref(10); let pollTimer: number | undefined; let clockTimer: number | undefined
const history = ref<ConversationEntry[]>([])
const suggestions = ['写一段产品介绍', '帮我分析这份需求', '生成一张写实人像']; const imageSizes = [{ label: '1024 × 1024', value: '1024x1024' }, { label: '1536 × 1024', value: '1536x1024' }, { label: '1024 × 1536', value: '1024x1536' }]
const availableModels = computed(() => models.value.map(item => ({ label: `${item.name} · ${item.source === 'ollama' ? 'Ollama' : item.format}`, value: item.id, disabled: !item.available }))); const selectedModel = computed(() => models.value.find(item => item.id === modelId.value)); const selectedModelName = computed(() => selectedModel.value?.name || 'ModelDock'); const activeCapability = computed(() => { const task = selectedModel.value?.task?.map(item => item.toLowerCase()) || []; if (task.some(item => item.includes('video'))) return '视频'; if (task.some(item => item.includes('audio') || item.includes('speech'))) return '音频'; if (task.some(item => item.includes('image') || item.includes('diffusion'))) return '图片'; return '文本' }); const capabilities = computed(() => [activeCapability.value]); const capabilityLabel = computed(() => `${activeCapability.value}模型`); const composerPlaceholder = computed(() => activeCapability.value === '图片' ? '描述你想生成的画面…' : activeCapability.value === '视频' ? '描述视频内容或上传参考素材…' : activeCapability.value === '音频' ? '描述声音、音乐或旁白…' : '给模型发送消息…')
let currentAssistant: ChatItem | undefined
function loadHistory() { history.value = JSON.parse(localStorage.getItem('modeldock-conversations') || '[]') }
function saveHistory(title?: string) { const current = history.value.find(item => item.id === conversationId.value); if (current) { current.updatedAt = new Date().toLocaleString(); if (title && current.title === '新对话') current.title = title } else history.value.unshift({ id: conversationId.value, title: title || '新对话', updatedAt: new Date().toLocaleString() }); localStorage.setItem('modeldock-conversations', JSON.stringify(history.value)) }
function renameConversation(id: string) { const item = history.value.find(entry => entry.id === id); if (!item) return; let title = item.title; Modal.confirm({ title: '重命名对话', content: h(Input, { value: title, maxlength: 80, autofocus: true, placeholder: '请输入对话主题', 'onUpdate:value': (value: string) => { title = value } }), okText: '保存', cancelText: '取消', onOk() { const nextTitle = title.trim(); if (!nextTitle) { message.warning('对话主题不能为空'); return Promise.reject() } item.title = nextTitle; item.updatedAt = new Date().toLocaleString(); localStorage.setItem('modeldock-conversations', JSON.stringify(history.value)); return Promise.resolve() } }) }
function deleteConversation(id: string) { const item = history.value.find(entry => entry.id === id); if (!item) return; Modal.confirm({ title: '删除对话', content: `删除对话“${item.title}”？聊天内容也会从本机移除。`, okText: '删除', cancelText: '取消', okType: 'danger', onOk() { history.value = history.value.filter(entry => entry.id !== id); localStorage.removeItem(`modeldock-chat-${id}`); localStorage.setItem('modeldock-conversations', JSON.stringify(history.value)); if (id === conversationId.value) newChat(false) } }) }
function switchConversation(id: string) { if (running.value) { message.warning('当前对话正在运行，请完成后再切换'); return }; conversationId.value = id; localStorage.setItem('modeldock-active-conversation', id); messages.value = JSON.parse(localStorage.getItem(`modeldock-chat-${id}`) || '[]'); job.value = undefined; elapsed.value = '00:00'; currentAssistant = undefined; scrollBottom() }
function recoverInterruptedMessages() { let changed = false; messages.value.forEach(item => { if (item.role !== 'assistant' || !item.running) return; item.running = false; item.processStatus = 'stopped'; item.interrupted = true; item.stepsOpen = ['process']; item.steps?.forEach(step => { if (step.status === 'running') { step.status = 'stopped'; step.detail = '服务已重启，任务已停止' } }); changed = true }); if (changed) persist() }
function retryMessage(item: ChatItem) { if (running.value) return; const index = messages.value.indexOf(item); const previous = index > 0 ? messages.value[index - 1] : undefined; if (!previous || previous.role !== 'user' || !previous.content) { message.warning('找不到这次任务的原始提示词'); return } prompt.value = previous.content; send() }
function beforeUpload(file: File) { image.value = file; return false }; function formatClock(seconds: number) { return `${String(Math.floor(seconds / 60)).padStart(2, '0')}:${String(seconds % 60).padStart(2, '0')}` }; function formatDuration(step: Step) { if (!step.startedAt) return '未开始'; const start = Date.parse(step.startedAt); const finish = step.finishedAt ? Date.parse(step.finishedAt) : Date.now(); return formatClock(Math.max(0, Math.floor((finish - start) / 1000))) }; function tick() { if (startedAt.value) elapsed.value = formatClock(Math.floor((Date.now() - startedAt.value) / 1000)) }; function persist() { localStorage.setItem(`modeldock-chat-${conversationId.value}`, JSON.stringify(messages.value)) }; function scrollBottom() { nextTick(() => { if (messageList.value) messageList.value.scrollTop = messageList.value.scrollHeight }) }
function defaultSteps(): Step[] { return ['分析需求', '规划运行方案', '加载模型', '执行生成', '测试结果'].map((label, index) => ({ key: ['analyzing', 'planning', 'loading', 'acting', 'testing'][index], label, status: 'pending', startedAt: '', index: index + 1 })) }
async function send() { if (running.value) return; if (!modelId.value) { message.warning('请先选择模型'); return }; if (!prompt.value.trim()) return; const text = prompt.value.trim(); prompt.value = ''; saveHistory(text.slice(0, 28)); messages.value.push({ id: `user-${Date.now()}`, role: 'user', content: text, createdAt: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) }); currentAssistant = { id: `assistant-${Date.now()}`, role: 'assistant', content: '', steps: defaultSteps(), stepsOpen: ['process'], running: true, processStatus: 'running' }; messages.value.push(currentAssistant); persist(); scrollBottom(); running.value = true; job.value = undefined; startedAt.value = Date.now(); tick(); clockTimer = window.setInterval(tick, 1000); try { let imagePath = ''; if (image.value) imagePath = (await api.upload(image.value)).path; const submitted = await api.generate(modelId.value, text, imagePath, { size: imageSize.value, steps: imageSteps.value, guidance: imageGuidance.value, seed: imageSeed.value, promptExpansion: promptExpansion.value }, conversationId.value, messages.value.filter(item => item.content).map(item => ({ role: item.role, content: item.content }))); if (submitted.status === 'not_ready') throw new Error(submitted.message || '当前模型不可用'); image.value = undefined; await poll(submitted.id) } catch (error) { if (currentAssistant) { currentAssistant.processStatus = 'error'; currentAssistant.running = false; currentAssistant.stepsOpen = ['process'] }; running.value = false; window.clearInterval(clockTimer); message.error(error instanceof Error ? error.message : '提交模型任务失败'); persist() } }
async function poll(id: string) { const read = async () => { try { job.value = await api.generationJob(id); stepMessage.value = job.value.message || '正在运行'; if (currentAssistant) { currentAssistant.steps = (job.value.steps || defaultSteps()).map((step, index) => ({ ...step, index: index + 1 })); currentAssistant.running = job.value.status !== 'completed' && job.value.status !== 'failed'; currentAssistant.processStatus = job.value.status === 'failed' ? 'error' : job.value.status === 'completed' ? 'done' : 'running'; if (job.value.status === 'completed' || job.value.status === 'failed') currentAssistant.stepsOpen = job.value.status === 'failed' ? ['process'] : [] } if (job.value.status === 'completed' || job.value.status === 'failed') { tick(); running.value = false; window.clearInterval(clockTimer); if (currentAssistant) currentAssistant.duration = elapsed.value; if (job.value.status === 'completed') { if (job.value.response) currentAssistant!.content = job.value.response; currentAssistant!.artifactURL = job.value.artifactURL; currentAssistant!.artifactName = job.value.artifactName; currentAssistant!.artifactType = job.value.artifactURL && /\.(png|jpg|jpeg|webp)$/i.test(job.value.artifactURL) ? 'image' : job.value.artifactURL && /\.(mp3|wav|ogg)$/i.test(job.value.artifactURL) ? 'audio' : 'video'; persist(); scrollBottom() } else message.error(job.value.error || '模型运行失败'); return true } return false } catch { tick(); running.value = false; window.clearInterval(clockTimer); if (currentAssistant) { currentAssistant.running = false; currentAssistant.processStatus = 'stopped'; currentAssistant.interrupted = true; currentAssistant.duration = elapsed.value; currentAssistant.stepsOpen = ['process']; currentAssistant.steps?.forEach(step => { if (step.status === 'running') { step.status = 'stopped'; step.detail = '任务状态暂时无法获取' } }) }; message.error('任务状态获取失败，服务可能已重启，可点击“继续任务”重新运行'); persist(); return true } }; if (await read()) return; pollTimer = window.setInterval(async () => { if (await read()) window.clearInterval(pollTimer) }, 1000) }
function stopRun() { message.info('当前运行会在服务端完成后停止显示；取消接口将在运行时支持后启用') }; function newChat(saveToHistory = true) { window.clearInterval(pollTimer); window.clearInterval(clockTimer); conversationId.value = `conversation-${Date.now()}-${Math.random().toString(16).slice(2)}`; localStorage.setItem('modeldock-active-conversation', conversationId.value); messages.value = []; job.value = undefined; running.value = false; currentAssistant = undefined; elapsed.value = '00:00'; if (saveToHistory) saveHistory() }
onMounted(async () => { localStorage.setItem('modeldock-active-conversation', conversationId.value); loadHistory(); saveHistory(); models.value = await api.models(); modelId.value = models.value.find(item => item.source === 'ollama' && item.available)?.id || models.value.find(item => item.available)?.id || ''; const saved = localStorage.getItem(`modeldock-chat-${conversationId.value}`); if (saved) messages.value = JSON.parse(saved); recoverInterruptedMessages(); scrollBottom() }); watch(messages, () => { persist(); if (messages.value.length) saveHistory() }, { deep: true }); onUnmounted(() => { window.clearInterval(pollTimer); window.clearInterval(clockTimer) })
</script>
